/**
 * ============================================================================
 * data.js - Language Units Dataset & In-Memory Vocabulary Cache
 * ============================================================================
 * 
 * NOTE FOR AI AGENTS & LLMs:
 * DO NOT read, grep, or edit the KR_EN_languageUnits array in this file directly!
 * This dataset is 170+ KB and contains 1,000+ units, which will consume tens of
 * thousands of tokens.
 *
 * Always use `select.js` to inspect, query, insert, or update language units:
 *   - Query to TSV/JSON : node select.js "SELECT Id, Korean, English WHERE Source = '...'"
 *   - Count units       : node select.js "COUNT WHERE Source = '...'"
 *   - Find next Id      : node select.js "SELECT Id ORDER BY Id DESC LIMIT 1"
 *   - Insert units      : node select.js INSERT FROMFILE new_units.json --source <tag>
 *   - Update units      : node select.js UPDATE col1, col2 FROMFILE slice.json
 *
 * Run `node select.js --help` for full schema, column aliases, and query syntax.
 */

/**
 * ============================================================================
 * ARCHITECTURE & DATA SCHEMA SPECIFICATION
 * ============================================================================
 *
 * 1. Dual-Pipeline Architecture
 * -----------------------------
 * Kongbuhey operates two complementary linguistic pipelines:
 *
 *  [A] Forward Generation Pipeline (korean.js, exhaustive.js):
 *      - Uses `Conjugation` formulas (e.g. ["{VP_AVst}으/니까 {Clause}"]) to recursively expand templates.
 *      - Uses `SemanticTags` to select compatible arguments (e.g. food objects with eating verbs).
 *      - Uses `SemanticVector` to enforce discourse logic and polarity matching (e.g. positive reason with positive outcome).
 *      - Strictly DOES NOT use `SyntaxFrame`.
 *
 *  [B] Reverse Analysis & Ingestion Pipeline (text_analyzer.js):
 *      - Takes natural Korean study texts and decomposes them using declarative suffix/particle tables sorted by syllable length.
 *      - Uses `SyntaxFrame` (reverse regex grammar patterns) to disambiguate homonyms and structural roles based on surrounding tokens.
 *      - Strictly DOES NOT use `Conjugation` expansion formulas.
 *
 * 2. DATA_SCHEMA Column Definitions & Primary Consumers
 * -----------------------------------------------------
 * Every row in KR_EN_languageUnits is an array formatted according to DATA_SCHEMA:
 *
 *  0. Id (number): Unique sequential integer primary key (0..N).
 *     - Primary Consumer: All tooling, indexing, caching.
 *  1. Korean (string): Surface form or dictionary lemma (with trailing -다 for verbs/adjectives).
 *     - Primary Consumer: All tooling.
 *  2. English (string): English definition, contextual gloss, and explanation.
 *     - Primary Consumer: UI & Study texts.
 *  3. PartofSpeech (string): Canonical category: "Noun", "Action Verb", "Descriptive Verb",
 *     "Adverb", "Grammar", "Pronoun", "Number", "Exclamation", "Determiner".
 *     - Primary Consumer: Filter & Cache engines.
 *  4. SemanticTags (string[] / Set<string>): Lexical classification & selectional restriction tags
 *     (e.g. "transitive_food", "transitive_place", "descriptive_person", "clothing").
 *     - Primary Consumer: findNounForVerbTag in korean.js.
 *  5. Disambiguation (string): Short human/LLM label to differentiate homonyms
 *     (e.g. "snow vs eye", "person/hour counter").
 *     - Primary Consumer: homonyms.js.
 *  6. Conjugation (string | string[]): Conjugation rule identifier for verbs/adjectives
 *     (e.g. "regular", "p_irregular", "stem_vowel_a") or forward template expansion formulas
 *     for Grammar units (e.g. ["{VP_AVst}으/니까 {Clause}"]).
 *     - Primary Consumer: korean.js, exhaustive.js.
 *  7. Source (string): Curriculum origin lesson tag (e.g. "SUOBI01", "class2012").
 *     - Primary Consumer: Curriculum filters.
 *  8. PriorityScore (number): TOPIK pedagogical frequency/urgency tier (1 = core vocabulary, 5 = niche).
 *     - Primary Consumer: Learning order & prioritization.
 *  9. FormalityLevel (string): Speech register: "informal_low", "polite", "formal_high", etc.
 *     - Primary Consumer: Morphology engine.
 * 10. HonorificRules (string): Sociolinguistic constraints and honorific alternatives
 *     (e.g. replace with 말씀하시다 for respected subjects).
 *     - Primary Consumer: Honorific generation & concord tests.
 * 11. SemanticData (string (JSON)): Structured semantic, morphological, valency, and English realization metadata
 *     (formerly `SemanticVector`):
 *     - Grammar units: {"logic": "cause_effect" | "contrast" | ..., "en": {"lit": "...", "frame": "..."}}
 *     - Content words: {"domain": "...", "polarity": -1|0|1, "req"?: "...", "en": {"lit": "...", "nat": "..."}}
 *     - Primary Consumer: expandSemanticVerb & translation engines in korean.js.
 * 12. SyntaxFrame (string): Regex reverse-grammar collocation template for parsing/reading text.
 *     - Primary Consumer: text_analyzer.js (strictly not used during phrase generation).
 *
 * 3. Deep-Dive: SemanticData vs. SemanticTags vs. SyntaxFrame
 * ----------------------------------------------------------
 *  - SemanticTags (Selectional Restrictions):
 *    Determines which nouns pair with which verbs/adjectives. Declaratively matched in
 *    ACTION_VERB_SPECS and DESCRIPTIVE_VERB_SPECS in korean.js.
 *    Example: 사과 (tag: "food") paired with 먹다 (tag: "transitive_food") produces "사과를 먹다".
 *
 *  - SemanticData (Discourse Flow, Valency & Bilingual Translation Metadata):
 *    Controls multi-clause coherence, cause-and-effect transitions, sentiment consistency, and English realization:
 *    * cause_effect (-(으)니까, -아서/어서): Enforces verb.polarity === currentContext.polarity
 *      (positive reason leads to positive outcome; negative problem leads to negative outcome).
 *    * contrast (-는데, -지만): Enforces verb.polarity !== currentContext.polarity
 *      (positive premise leads to negative turn).
 *    * req / prod: Action chains (e.g. 배우다: req "language" -> prod "knowledge").
 *    * en: Structured English literal (Korean-word-order) and natural (SVO) inflection/gloss metadata.
 *    * TODO: Explanatory notes for pending logical constraints to be implemented in generator.
 *
 *  - SyntaxFrame (Reading / Parsing Only):
 *    Collocation regex pattern used exclusively when READING text in text_analyzer.js to
 *    disambiguate homonyms and recognize grammatical particles (e.g. differentiating -(으)로
 *    instrumental particle from noun homonyms, or adnominal endings from connectives).
 *    Strictly NEVER consulted during forward sentence generation.
 *    Note: Regex for simple patterns. Can be JavaScript expression for complex grammars, like
 *    `-기 때문에`, `-지 않다`, `-을 수 있다`, etc.
 */
const DATA_SCHEMA = {
	Id: 0,
	Korean: 1,
	English: 2,
	PartofSpeech: 3,
	SemanticTags: 4, // Array<string> in raw definition; replaced with Set<string> when added to main language units list via addLearningUnit
	Disambiguation: 5,
	Conjugation: 6,
	Source: 7,
	PriorityScore: 8,
	FormalityLevel: 9,
	HonorificRules: 10,
	SemanticData: 11,
	SyntaxFrame: 12,
	0: 'Id',
	1: 'Korean',
	2: 'English',
	3: 'PartofSpeech',
	4: 'SemanticTags',
	5: 'Disambiguation',
	6: 'Conjugation',
	7: 'Source',
	8: 'PriorityScore',
	9: 'FormalityLevel',
	10: 'HonorificRules',
	11: 'SemanticData',
	12: 'SyntaxFrame'
};
// Non-enumerable backward-compatible alias so legacy scripts referencing DATA_SCHEMA.SemanticVector still resolve index 11
Object.defineProperty(DATA_SCHEMA, 'SemanticVector', {
	value: 11,
	enumerable: false,
	writable: false,
	configurable: false
});
Object.freeze(DATA_SCHEMA);

// --- In-Memory Fast Lookup Cache & Helper Functions ---
// Navigate to language units in the cache with `cache[partsOfSpeech][tag]`, or `cache[source]._all`
const cache = {};

function addLearningUnit(unit) {
	let index = unit[DATA_SCHEMA.Id];
	if (index === undefined || typeof index !== 'number') {
		index = KR_EN_languageUnits.indexOf(unit);
		if (index < 0) {
			index = KR_EN_languageUnits.length;
			KR_EN_languageUnits.push(unit);
		}
		unit[DATA_SCHEMA.Id] = index;
	}
	const pos = unit[DATA_SCHEMA.PartofSpeech];
	const src = unit[DATA_SCHEMA.Source];
	const rawTags = unit[DATA_SCHEMA.SemanticTags] || [];
	const tagsSet = (rawTags instanceof Set) ? rawTags : new Set(rawTags);
	unit[DATA_SCHEMA.SemanticTags] = tagsSet;

	if (!cache[pos]) {
		cache[pos] = { _all: [] };
	}
	if (!cache[src]) {
		cache[src] = { _all: [] };
	}
	cache[pos]._all.push(unit);
	cache[src]._all.push(unit);
	tagsSet.forEach(tag => {
		if (!cache[pos][tag]) {
			cache[pos][tag] = [];
		}
		cache[pos][tag].push(unit);
	});
	// Substantives: Pronouns function as nominals (체언) and are included in the Noun cache
	if (pos === "Pronoun") {
		if (!cache["Noun"]) {
			cache["Noun"] = { _all: [] };
		}
		cache["Noun"]._all.push(unit);
		tagsSet.forEach(tag => {
			if (!cache["Noun"][tag]) {
				cache["Noun"][tag] = [];
			}
			cache["Noun"][tag].push(unit);
		});
	}
	// Exclamations/Interjections: Sentence-level modifiers (감탄사) included in Adverb cache
	if (pos === "Exclamation") {
		if (!cache["Adverb"]) {
			cache["Adverb"] = { _all: [] };
		}
		cache["Adverb"]._all.push(unit);
		tagsSet.forEach(tag => {
			if (!cache["Adverb"][tag]) {
				cache["Adverb"][tag] = [];
			}
			cache["Adverb"][tag].push(unit);
		});
	}
}

function rebuildCache() {
	for (let key in cache) delete cache[key];
	KR_EN_languageUnits.forEach((unit, idx) => {
		unit[DATA_SCHEMA.Id] = idx;
		addLearningUnit(unit);
	});
}

function getWords(pos, requiredTag = null) {
	if (!cache[pos]) return [];
	if (!requiredTag) return cache[pos]._all || [];
	return cache[pos][requiredTag] || [];
}

function getPartOfSpeechCached(tagName) {
	let partsOfSpeech = [];
	for (const [key, value] of Object.entries(cache)) {
		if (value[tagName]) { partsOfSpeech.push(key); }
	}
	return partsOfSpeech;
}

function hasTag(unit, ...tags) {
	if (!unit) return false;
	const unitTags = unit[DATA_SCHEMA.SemanticTags];
	if (!unitTags) return false;
	if (unitTags instanceof Set) {
		if (tags.length === 1) return unitTags.has(tags[0]);
		for (let i = 0; i < tags.length; i++) {
			if (unitTags.has(tags[i])) return true;
		}
		return false;
	}
	if (Array.isArray(unitTags)) {
		if (tags.length === 1) return unitTags.includes(tags[0]);
		return tags.some(t => unitTags.includes(t));
	}
	return false;
}

